states.a84dcf3c0cd3:
[
 {
  "zaman": "29.09.2026 14:02",
  "gonderen": "müşteri",
  "mesaj": "Merhaba, hesabımdan para gönderemiyorum, 'İşleminiz gerçekleştirilemedi' diyor. Tur şirketine kalan ödemeyi yapmam lazım, yarın son gün."
 },
 {
  "zaman": "29.09.2026 14:04",
  "gonderen": "temsilci",
  "mesaj": "Merhaba Doruk Bey, ben Selin. Hesabınızı kontrol ediyorum, lütfen ayrılmayın."
 },
 {
  "zaman": "29.09.2026 14:09",
  "gonderen": "temsilci",
  "mesaj": "Hesabınızda bankamız tarafından uygulanan geçici bir işlem kısıtlaması bulunuyor. Herhangi bir mahkeme, icra ya da kamu kurumu blokesi görünmüyor."
 },
 {
  "zaman": "29.09.2026 14:10",
  "gonderen": "müşteri",
  "mesaj": "Harika ya, tam ödeme gününden bir gün önce. Zamanlamanız kusursuz, tebrik ederim 👏"
 },
 {
  "zaman": "29.09.2026 14:11",
  "gonderen": "müşteri",
  "mesaj": "Ne yaptım ben? Bölümden 38 kişinin Kapadokya gezisi için otel ve otobüs parasını topladım, hepsi bu. Açıklamalara 'kapadokya', 'gezi' yazdılar zaten. Bir arkadaş da geçen ayki borcunu göndermiş, o 'borç' yazmış, onu saymayın."
 },
 {
  "zaman": "29.09.2026 14:13",
  "gonderen": "temsilci",
  "mesaj": "Anlıyorum. 5549 sayılı Kanun ve MASAK düzenlemeleri kapsamında, hesabınıza kısa sürede çok sayıda farklı kişiden gelen tutarlarla ilgili bilgi ve belge almamız gerekiyor. Ödemelerin amacını gösteren belgeleri (tur sözleşmesi, katılımcı listesi, tur şirketinin faturası) mobil uygulamadaki 'Belge Yükle' bölümünden iletebilirsiniz."
 },
 {
  "zaman": "29.09.2026 14:15",
  "gonderen": "müşteri",
  "mesaj": "MASAK mı?? Süper. Beni MASAK'a ihbar ettiniz herhalde, çok teşekkürler 🙂 Öğrenciyim ben, kara para aklayacak halim mi var."
 },
 {
  "zaman": "29.09.2026 14:16",
  "gonderen": "temsilci",
  "mesaj": "Müşterilerimizle ilgili herhangi bir bildirim yapılıp yapılmadığı konusunda bilgi paylaşamıyoruz; bu kural tüm müşterilerimiz için geçerlidir. Belgeleriniz incelendikten sonra kısıtlama yeniden değerlendirilecektir."
 },
 {
  "zaman": "29.09.2026 14:18",
  "gonderen": "müşteri",
  "mesaj": "Tabii tabii, hatta hesabımı da kapatın, bursumu da siz alın, tam olsun. 7 yıllık müşterinizim, ne güzel ödüllendirdiniz."
 },
 {
  "zaman": "29.09.2026 14:19",
  "gonderen": "müşteri",
  "mesaj": "Neyse. Tur sözleşmesini ve katılımcı listesini bu akşam yüklerim. Ben sadece kısıtlamanın kalkmasını ve yarın tur şirketine ödemeyi yapabilmeyi istiyorum."
 },
 {
  "zaman": "29.09.2026 14:21",
  "gonderen": "temsilci",
  "mesaj": "Teşekkür ederiz. Belgeleriniz ulaştığında öncelikli olarak incelenmesi için not düşüyorum."
 },
 {
  "zaman": "29.09.2026 14:22",
  "gonderen": "müşteri",
  "mesaj": "Çok yardımcı oldunuz gerçekten, 20 dakikadır aynı cümleleri okuyorsunuz. Bu iş yarına kadar çözülmezse BDDK'ya ve CİMER'e yazacağım, haberiniz olsun."
 }
]
